INSERT INTO public.hr_questions (category, question, key_evaluation_points) VALUES
('Introduction', 'Tell me about yourself and walk me through your journey in technology.', '["Structured narrative (Present -> Past -> Future)", "Key technical achievements", "Clarity and confidence", "Conciseness"]'::jsonb),
('Behavioral', 'Tell me about a time when you faced a difficult technical challenge or bug and how you resolved it.', '["STAR method (Situation, Task, Action, Result)", "Root cause analysis capability", "Persistence and learning outcomes"]'::jsonb),
('Situational', 'How do you handle disagreement with a teammate or technical lead regarding an architectural decision?', '["Empathy & professional communication", "Data-driven decision making", "Commitment to team alignment"]'::jsonb),
('Motivational', 'Why do you want to join this company and what makes you a great fit for this role?', '["Alignment with company vision", "Value proposition of candidate skills", "Long-term enthusiasm"]'::jsonb),
('Behavioral', 'What are your greatest strengths and an area you are actively working to improve?', '["Self-awareness", "Concrete examples of strengths", "Constructive, actionable growth mindset for weaknesses"]'::jsonb);
